-- ==========================================================================
-- BELPA BOUTIQUE - INSERT MASIVO DE LOS 79 PRODUCTOS ORIGINALES
-- ==========================================================================

ON CONFLICT (id) DO UPDATE SET
name = EXCLUDED.name,
brand = EXCLUDED.brand,
category = EXCLUDED.category,
filter_category = EXCLUDED.filter_category,
price = EXCLUDED.price,
raw_price = EXCLUDED.raw_price,
badge = EXCLUDED.badge,
description = EXCLUDED.description,
images = EXCLUDED.images,
media_id = EXCLUDED.media_id,
is_active = EXCLUDED.is_active;

-- Ajustar el contador de secuencia SERIAL al ID más alto (79)
SELECT setval('public.products_id_seq', (SELECT MAX(id) FROM public.products));
